def cross_block_nonce_ok(b, off):
    """放入捆绑 b 到 off 块后，相邻区块间 nonce 是否仍可能递增。

    仅检查必要条件（与块内段排列无关）：同发送者在前一占用块的
    最大 nonce 小于本块最小 nonce，本块最大 nonce 小于后一占用块
    最小 nonce。范围只会随后续放入扩大，故一旦冲突即永久冲突；
    中间空块不产生约束，只是少剪枝，不会误剪。
    """
    for sender, (lo, hi) in sender_ranges[b].items():
        cur = range_by_block[off].get(sender)
        new_lo = lo if cur is None else min(cur[0], lo)
        new_hi = hi if cur is None else max(cur[1], hi)
        if off > 0:
            prev = range_by_block[off - 1].get(sender)
            if prev is not None and prev[1] >= new_lo:
                return False
        if off + 1 < window:
            nxt = range_by_block[off + 1].get(sender)
            if nxt is not None and new_hi >= nxt[0]:
                return False
    return True

def commit(b, off):
    """合并捆绑 b 的发送者范围到 off 块，返回被改发送者的旧值用于还原。"""
    loads[off] += sizes[b]
    assigned[off].add(b)
    saved = []
    rng = range_by_block[off]
    for sender, (lo, hi) in sender_ranges[b].items():
        cur = rng.get(sender)
        saved.append((sender, cur))
        rng[sender] = (
            lo if cur is None else min(cur[0], lo),
            hi if cur is None else max(cur[1], hi),
        )
    return saved

def rollback(b, off, saved):
    loads[off] -= sizes[b]
    assigned[off].discard(b)
    rng = range_by_block[off]
    for sender, cur in saved:
        if cur is None:
            del rng[sender]
        else:
            rng[sender] = cur

